// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"es","term":"Ethereum (ETH)","aka":["ETH","Ether"],"short":"Ethereum es una blockchain programable que ejecuta contratos inteligentes, y Ether (ETH) es su moneda nativa, que se usa para pagar las comisiones de gas y para hacer staking.","body":[[["Bitcoin","bitcoin"]," se diseñó sobre todo para transferir valor. Ethereum, lanzado en 2015, añadió la posibilidad de ejecutar programas en la ",["blockchain","blockchain"],": los contratos inteligentes. Sobre ellos funcionan exchanges descentralizados, ",["préstamos DeFi","defi-lending"],", ",["stablecoins","stablecoin"],", ",["NFT","nft"]," y miles de tokens."],["Cada operación consume gas, que se paga en ETH. Cuando la red está congestionada, el gas sube. Para abaratar el uso surgieron las redes ",["layer 2","layer-2"],", como Arbitrum, Optimism o Base, que procesan transacciones fuera de la cadena principal y luego las anclan en Ethereum."],"Desde septiembre de 2022 (The Merge), Ethereum funciona con prueba de participación: los validadores bloquean ETH como garantía en lugar de minar. Por eso puedes hacer staking de ETH, directamente o a través de un exchange o un protocolo de staking líquido."],"example":"Supón que quieres intercambiar tokens en un DEX de la red principal de Ethereum. La operación gasta 150.000 unidades de gas y el precio del gas es de 10 gwei. El coste es 150.000 × 10 = 1.500.000 gwei, es decir, 0,0015 ETH. Con ETH a 3.000 USDT, pagas 4,5 USDT de gas. Si la misma operación se hace en una layer 2, el coste suele ser una fracción de eso.","mistakes":["Quedarte sin ETH en tu wallet y no poder mover tus tokens porque no tienes con qué pagar el gas.","Confundir la red principal de Ethereum con una layer 2 al depositar o retirar en un exchange.","Pensar que todo token que funciona en Ethereum tiene el mismo valor o respaldo que el ETH."],"faq":[{"q":"¿Qué diferencia hay entre Ethereum y Ether?","a":"Ethereum es la red y Ether (ETH) es su moneda nativa. En el día a día mucha gente usa ambos nombres como sinónimos."},{"q":"¿Ethereum tiene un suministro máximo?","a":"No tiene un límite fijo como Bitcoin. Su emisión depende de las recompensas de staking y parte de las comisiones se quema, así que el suministro puede subir o bajar según la actividad."}],"title":"¿Qué es Ethereum (ETH)? Significado y para qué sirve","description":"Qué es Ethereum, para qué sirve el ETH, cómo se calcula el gas y qué cambió con el paso a prueba de participación en 2022.","related":[["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."],["gas-fee","Comisión de gas (gas fee)","La comisión de gas (gas fee) es lo que pagas a una blockchain como Ethereum por procesar tu transacción, y depende de cuánto cálculo requiere la operación y de lo congestionada que esté la red."],["proof-of-stake","Prueba de participación (proof of stake, PoS)","La prueba de participación (PoS) es un mecanismo de consenso en el que los validadores bloquean monedas como garantía para proponer y confirmar bloques, y pueden perder parte de ellas si actúan de forma deshonesta."],["layer-2","Capa 2 (layer 2, L2)","Una capa 2 (layer 2 o L2) es una red construida sobre una blockchain base que procesa transacciones fuera de ella y publica los resultados en la cadena principal para abaratar comisiones sin renunciar del todo a su seguridad."],["defi","DeFi (finanzas descentralizadas)","DeFi, o finanzas descentralizadas, es el conjunto de servicios financieros, como intercambios, préstamos o rendimientos, que funcionan mediante contratos inteligentes en una blockchain sin un intermediario central."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"es","term":"Capa 1 (layer 1, L1)","aka":["L1","layer 1","blockchain base"],"short":"Una capa 1 (layer 1 o L1) es una blockchain base que procesa y asegura sus propias transacciones con su propio consenso y su moneda nativa, como Bitcoin, Ethereum o Solana.","body":[["La L1 es la cadena principal: guarda el historial definitivo, define las reglas y recompensa a mineros o validadores. Todo lo que se construye encima, como tokens, aplicaciones o redes de ",["capa 2","layer-2"],", depende en última instancia de su seguridad."],["Cada L1 elige un equilibrio distinto entre descentralización, seguridad y velocidad. ",["Bitcoin","bitcoin"]," prioriza la seguridad y la simplicidad; ",["Ethereum","ethereum"],", la programabilidad; Solana busca mucha velocidad con requisitos de hardware más altos. Por eso las comisiones y los tiempos de confirmación varían tanto entre redes."],["Cuando una L1 se congestiona, las comisiones suben. Una solución es escalar la propia L1; otra es mover actividad a capas 2 que heredan su seguridad. Al depositar en un exchange verás ambas ",["opciones","options"]," como redes distintas."]],"example":["Supón que quieres enviar 100 ",["USDC","usdc"],". En la red principal de Ethereum, con mucha congestión, el gas podría costarte 3 ",["USDT","usdt"],". En otra L1 más barata podrías pagar 0,01 USDT. En ambos casos el destino recibe 100 USDC, pero solo si la dirección y el exchange admiten esa red concreta. Si eliges una red no compatible, el depósito puede no llegar y recuperarlo, cuando es posible, suele ser lento."],"mistakes":["Pensar que la L1 más barata es siempre la mejor, sin mirar seguridad ni liquidez.","Elegir una red al retirar sin confirmar que el destino la admite.","Creer que todas las L1 son compatibles entre sí y que los fondos pasan solos de una a otra."],"faq":[{"q":"¿Qué diferencia hay entre layer 1 y layer 2?","a":"La L1 es la blockchain base con su propio consenso. La L2 procesa transacciones aparte y publica los resultados en una L1 para apoyarse en su seguridad."},{"q":"¿Qué ejemplos de L1 hay?","a":"Bitcoin, Ethereum, Solana, BNB Chain, Avalanche, Cardano y Tron son ejemplos de blockchains de capa 1."}],"title":"¿Qué es una layer 1 (L1) en cripto? Significado","description":"Qué es una blockchain de capa 1, ejemplos como Bitcoin, Ethereum y Solana, y en qué se diferencia de una red de capa 2.","related":[["layer-2","Capa 2 (layer 2, L2)","Una capa 2 (layer 2 o L2) es una red construida sobre una blockchain base que procesa transacciones fuera de ella y publica los resultados en la cadena principal para abaratar comisiones sin renunciar del todo a su seguridad."],["blockchain","Blockchain (cadena de bloques)","Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores."],["ethereum","Ethereum (ETH)","Ethereum es una blockchain programable que ejecuta contratos inteligentes, y Ether (ETH) es su moneda nativa, que se usa para pagar las comisiones de gas y para hacer staking."],["gas-fee","Comisión de gas (gas fee)","La comisión de gas (gas fee) es lo que pagas a una blockchain como Ethereum por procesar tu transacción, y depende de cuánto cálculo requiere la operación y de lo congestionada que esté la red."],["coin-vs-token","Moneda vs token (coin vs token)","Una moneda (coin) es el activo nativo de su propia blockchain, como BTC o ETH, mientras que un token se emite sobre una blockchain ya existente mediante un contrato inteligente, como USDT en Ethereum o Tron."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"es","term":"Quema de tokens (token burn)","aka":["token burn","quema","burn"],"short":"Una quema de tokens (token burn) es la eliminación permanente de tokens del suministro, enviándolos a una dirección de la que nadie puede sacarlos o destruyéndolos mediante el propio contrato.","body":[["Los tokens quemados siguen registrados en la ",["blockchain","blockchain"],", pero en una dirección sin ",["clave privada","private-key"]," conocida o descontados del suministro por el contrato. Así se reduce el suministro total o circulante de forma verificable."],["Hay quemas programadas y quemas automáticas. BNB, por ejemplo, tiene un mecanismo de quema periódica que se anuncia públicamente. En ",["Ethereum","ethereum"],", desde 2021 se quema la tarifa base del gas de cada transacción, por lo que el suministro de ETH depende también de la actividad de la red."],["Una quema reduce la oferta, pero no crea demanda. Si se queman pocos tokens en relación con la emisión nueva, el suministro sigue creciendo. Para valorar el efecto compara la cantidad quemada con el ",["suministro circulante","circulating-supply"]," y con los desbloqueos o la inflación del mismo periodo."]],"example":"Supón que un token tiene 500 millones de unidades en circulación y el proyecto quema 10 millones en un trimestre: un 2 % del circulante. En ese mismo trimestre se desbloquean 25 millones para el equipo. El resultado neto es que el circulante pasa a 515 millones, un 3 % más. Aunque el anuncio de quema suene bien, la oferta disponible creció.","mistakes":["Pensar que una quema garantiza que el precio suba.","No comparar la quema con la emisión o los desbloqueos del mismo periodo.","Fiarte del anuncio sin verificar la transacción de quema en un explorador de bloques."],"faq":[{"q":"¿Por qué un proyecto quema tokens?","a":"Para reducir el suministro, devolver valor a los holders o compensar la emisión. A veces también se quema para retirar tokens no vendidos tras una venta pública."},{"q":"¿Se pueden recuperar los tokens quemados?","a":"No. Si se envían a una dirección sin clave privada o el contrato los destruye, quedan fuera de circulación de forma permanente."}],"title":"¿Qué es una quema de tokens (token burn)?","description":"Qué es una quema de tokens, cómo se verifica en la blockchain, ejemplos como BNB o el gas de Ethereum, y por qué no garantiza subidas.","related":[["tokenomics","Tokenomics (tokenomía)","Tokenomics es el diseño económico de un token: cuántos existen, cómo se reparten, cuándo se liberan, para qué se usan y qué mecanismos aumentan o reducen su suministro."],["circulating-supply","Suministro circulante (circulating supply)","El suministro circulante es la cantidad de unidades de una criptomoneda que ya están disponibles y pueden negociarse en el mercado, sin contar las bloqueadas, reservadas o quemadas."],["market-capitalization","Capitalización de mercado (market cap)","La capitalización de mercado (market cap) de una criptomoneda es el precio de una unidad multiplicado por su suministro circulante, y sirve para comparar el tamaño de distintos proyectos."],["coin-vs-token","Moneda vs token (coin vs token)","Una moneda (coin) es el activo nativo de su propia blockchain, como BTC o ETH, mientras que un token se emite sobre una blockchain ya existente mediante un contrato inteligente, como USDT en Ethereum o Tron."]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"es","term":"FUD (miedo, incertidumbre y duda)","aka":["fear, uncertainty and doubt","miedo, incertidumbre y duda"],"short":"FUD (fear, uncertainty and doubt, miedo, incertidumbre y duda) es la difusión de noticias, rumores u opiniones negativas que generan miedo en el mercado, sean ciertas, exageradas o falsas.","body":["El término se usa para describir mensajes que provocan ventas por pánico: rumores de quiebra de un exchange, de prohibiciones, de hackeos o de que un gran inversor va a vender. A veces son campañas deliberadas; otras veces, preocupaciones legítimas.","El problema es que en la comunidad cripto muchos llaman FUD a cualquier crítica, incluso cuando está bien fundada. Algunos colapsos se anunciaron primero como \"FUD\" y resultaron ser ciertos. Descartar todo lo negativo es tan peligroso como creérselo todo.",["Ante una noticia alarmante, busca la fuente original: comunicados oficiales, datos en la ",["blockchain","blockchain"],", documentos de reguladores. Comprueba si hay movimientos reales de fondos y evita reaccionar con ",["apalancamiento","leverage"]," en los primeros minutos, cuando la ",["volatilidad","volatility"]," es mayor."]],"example":["Supón que circula el rumor de que un exchange va a congelar retiros, y el token del exchange cae de 12 a 9 ",["USDT","usdt"]," en una hora, un 25 %. Si vendes en pánico 100 unidades, recibes 900 USDT en lugar de los 1.200 que valían. Si antes de decidir revisas el anuncio oficial, su informe de ",["prueba de reservas","proof-of-reserves"]," y los flujos en la blockchain, tendrás una base mejor para decidir, sea mantener, reducir o retirar tus fondos."],"mistakes":["Vender todo en pánico al leer un rumor sin fuente verificable.","Llamar FUD a cualquier crítica y no revisar problemas reales.","Operar con apalancamiento justo en los minutos de máxima tensión."],"faq":[{"q":"¿Qué significa FUD en cripto?","a":"Son las siglas de fear, uncertainty and doubt. Se refiere a información negativa que provoca miedo y ventas, sea cierta o no."},{"q":"¿Cómo distinguir FUD de un riesgo real?","a":"Busca la fuente original, datos en la blockchain y comunicados oficiales. Si la información es verificable y concreta, trátala como un riesgo real aunque otros la llamen FUD."}],"title":"¿Qué es el FUD en cripto? Significado","description":"Qué significa FUD en cripto, cómo los rumores provocan ventas por pánico y cómo distinguir un riesgo real de una campaña de miedo.","related":[["fomo","FOMO (miedo a quedarse fuera)","FOMO (fear of missing out, miedo a quedarse fuera) es la presión emocional que lleva a comprar un activo porque está subiendo rápido y otros parecen estar ganando, sin un análisis ni un plan propio."],["bear-market","Mercado bajista (bear market)","Un mercado bajista (bear market) es un periodo prolongado de caída de precios, con máximos y mínimos cada vez más bajos y un ánimo general de pesimismo y poco interés."],["fear-and-greed-index","Índice de miedo y codicia (Fear and Greed Index)","El índice de miedo y codicia es un indicador de sentimiento que resume en una escala de 0 a 100 si el mercado cripto está dominado por el miedo o por la euforia."],["on-chain-analysis","Análisis on-chain","El análisis on-chain es el estudio de los datos públicos de una blockchain, como transacciones, direcciones y saldos, para entender cómo se comportan los usuarios, las ballenas y los exchanges."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Alguien dice que te hará ganar dinero. Primero mira qué te pide."},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"es","term":"Spread (diferencial de compra-venta)","aka":["spread","bid-ask spread","diferencial bid-ask","horquilla"],"short":"El spread o diferencial de compra-venta es la diferencia entre el mejor precio al que alguien quiere comprar (bid) y el mejor precio al que alguien quiere vender (ask) un activo en un momento dado.","body":[["Si en el ",["libro de órdenes","order-book"]," la mejor compra está en 99,90 y la mejor venta en 100,10, el spread es de 0,20, es decir, un 0,2 % del precio medio. Ese diferencial es un coste implícito: si compras a mercado y vendes a mercado al instante, pierdes el spread más las comisiones."],["En pares muy líquidos como ",["BTC","bitcoin"],"/",["USDT","usdt"]," en los grandes exchanges, el spread suele ser mínimo, a menudo de un solo tick. En ",["altcoins","altcoin"]," pequeñas o en horas de poca actividad puede ser mucho más amplio. Los creadores de mercado (market makers) ganan precisamente ofreciendo compras y ventas a ambos lados y capturando ese diferencial."],"Las apps de compra rápida o los servicios de conversión a veces no muestran una comisión explícita, pero aplican un spread más amplio. Comparar el precio que te ofrecen con el del libro de órdenes te dice cuánto pagas realmente."],"example":"Supón que un token tiene bid en 4,96 USDT y ask en 5,04 USDT. El precio medio es 5,00 y el spread es 0,08, un 1,6 %. Si compras 1.000 USDT a mercado, obtienes unas 198,4 unidades a 5,04. Si te arrepientes y vendes de inmediato a 4,96, recibes unos 984 USDT: has perdido 16 USDT sin que el precio se moviera, antes incluso de pagar comisiones.","mistakes":["Fijarte solo en la comisión del exchange e ignorar el spread, que puede costar más.","Operar altcoins pequeñas a mercado en horas de poca liquidez.","Pensar que una conversión \"sin comisión\" no tiene costes."],"faq":[{"q":"¿Qué es un spread alto?","a":"No hay una cifra fija, pero en pares grandes un spread por encima de unas pocas décimas porcentuales ya es amplio. En tokens pequeños puede llegar a varios puntos porcentuales."},{"q":"¿Cómo evito pagar el spread?","a":"Usando órdenes límite en lugar de órdenes de mercado. Así fijas tu precio y, si tu orden queda en el libro, actúas como maker."}],"title":"¿Qué es el spread (bid-ask) en cripto?","description":"Qué es el spread o diferencial de compra-venta, cómo se calcula en porcentaje y por qué es un coste oculto al comprar a mercado.","related":[["order-book","Libro de órdenes (order book)","El libro de órdenes (order book) es la lista en tiempo real de todas las órdenes de compra (bids) y de venta (asks) pendientes para un par, ordenadas por precio, que muestra a qué precios hay compradores y vendedores y en qué cantidad."],["slippage","Deslizamiento (slippage)","El deslizamiento (slippage) es la diferencia entre el precio que esperabas al enviar una orden y el precio medio al que realmente se ejecutó, causada por falta de liquidez o por movimientos rápidos del mercado."],["liquidity","Liquidez","La liquidez es la facilidad con la que puedes comprar o vender un activo rápidamente, en la cantidad que quieres, sin mover mucho su precio."],["market-maker","Market maker (creador de mercado)","Un market maker o creador de mercado es un participante que publica a la vez órdenes de compra y de venta en un mercado para aportar liquidez y ganar con el spread."],["maker-taker-fees","Comisiones maker y taker","Las comisiones maker y taker son las dos tarifas que cobra un exchange según tu orden añada liquidez al libro de órdenes (maker) o la retire al ejecutarse de inmediato (taker)."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"¿Por qué el precio en pantalla no es mi precio de ejecución?"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"es","term":"Deslizamiento (slippage)","aka":["slippage","deslizamiento de precio"],"short":"El deslizamiento (slippage) es la diferencia entre el precio que esperabas al enviar una orden y el precio medio al que realmente se ejecutó, causada por falta de liquidez o por movimientos rápidos del mercado.","body":[["En un ",["exchange centralizado","centralized-exchange"],", el deslizamiento aparece sobre todo con órdenes de mercado grandes: la orden consume el mejor nivel del libro y sigue con los siguientes, cada vez a peor precio. También ocurre en momentos de alta ",["volatilidad","volatility"],", cuando el precio cambia entre que pulsas el botón y la orden se ejecuta."],["En un ",["DEX","dex"]," con ",["pool de liquidez","liquidity-pool"],", cada compra mueve el precio según la fórmula del pool. Por eso las wallets te piden una tolerancia de deslizamiento, por ejemplo 0,5 % o 1 %. Si el precio final supera esa tolerancia, la transacción se revierte, aunque pagas el gas."],"Una tolerancia demasiado alta te expone a bots que se adelantan a tu operación y te venden más caro (ataques sándwich). Una tolerancia demasiado baja hace que tus operaciones fallen. Dividir órdenes grandes o usar órdenes límite reduce el deslizamiento."],"example":["Supón que quieres comprar 5.000 ",["USDT","usdt"]," de un token cuyo precio en pantalla es 0,250 USDT, así que esperas unas 20.000 unidades. El libro no tiene suficiente cantidad a ese precio y tu orden se llena a un precio medio de 0,255. Recibes 19.608 unidades. El deslizamiento es de 0,005 USDT por unidad, un 2 %, lo que equivale a unos 98 USDT de coste extra."],"mistakes":["Poner una tolerancia de deslizamiento del 10 % o más en un DEX sin necesidad.","Comprar a mercado grandes cantidades de un token poco líquido de una sola vez.","Confundir el deslizamiento con la comisión del exchange."],"faq":[{"q":"¿Qué tolerancia de deslizamiento debo poner?","a":"En pares líquidos suele bastar con 0,1 % a 0,5 %. En tokens con poca liquidez puede hacer falta más, pero cuanto más alta, mayor el riesgo de pagar de más."},{"q":"¿El deslizamiento puede ser positivo?","a":"Sí. Si el precio se mueve a tu favor mientras se ejecuta la orden, puedes obtener un precio mejor del esperado, aunque es menos habitual en órdenes grandes."}],"title":"¿Qué es el slippage (deslizamiento) en cripto?","description":"Qué es el slippage o deslizamiento, por qué pasa en exchanges y DEX, cómo calcularlo y qué tolerancia poner para no pagar de más.","related":[["bid-ask-spread","Spread (diferencial de compra-venta)","El spread o diferencial de compra-venta es la diferencia entre el mejor precio al que alguien quiere comprar (bid) y el mejor precio al que alguien quiere vender (ask) un activo en un momento dado."],["market-order","Orden de mercado (market order)","Una orden de mercado (market order) es una instrucción para comprar o vender de inmediato al mejor precio disponible en el libro de órdenes, priorizando la rapidez de ejecución sobre el precio exacto."],["liquidity","Liquidez","La liquidez es la facilidad con la que puedes comprar o vender un activo rápidamente, en la cantidad que quieres, sin mover mucho su precio."],["order-book","Libro de órdenes (order book)","El libro de órdenes (order book) es la lista en tiempo real de todas las órdenes de compra (bids) y de venta (asks) pendientes para un par, ordenadas por precio, que muestra a qué precios hay compradores y vendedores y en qué cantidad."],["amm","Creador de mercado automatizado (AMM)","Un creador de mercado automatizado (AMM) es un contrato inteligente que fija el precio de un intercambio con una fórmula basada en las reservas de un pool de liquidez, en lugar de emparejar órdenes de compradores y vendedores."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"¿Por qué el precio en pantalla no es mi precio de ejecución?"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"es","term":"Trailing stop (stop dinámico)","aka":["trailing stop","stop móvil","stop dinámico","stop de seguimiento"],"short":"Un trailing stop es una orden de stop que sigue al precio a una distancia fija, en porcentaje o en importe, cuando el mercado se mueve a tu favor, y que se activa si el precio retrocede esa distancia desde el mejor nivel alcanzado.","body":[["En una posición larga, el stop sube a medida que el precio marca nuevos máximos, pero nunca baja. Si el precio cae el porcentaje fijado desde su máximo, se envía la orden de cierre. En una ",["posición corta","short-selling"]," funciona al revés."],"Su ventaja es que protege ganancias sin tener que mover el stop a mano y te deja aprovechar tendencias largas. Algunos exchanges permiten fijar además un precio de activación: el trailing solo empieza a seguir al precio cuando se alcanza ese nivel.",["La clave es la distancia. Si es demasiado corta, un retroceso normal te saca de una tendencia que seguía sana. Si es demasiado amplia, devuelves buena parte de la ganancia. Ajustarla a la ",["volatilidad","volatility"]," del activo suele dar mejores resultados que un porcentaje fijo para todo."]],"example":["Supón que compras ",["BTC","bitcoin"]," a 60.000 ",["USDT","usdt"]," y pones un trailing stop del 5 %. El stop inicial queda en 57.000. El precio sube a 66.000 y el stop sube con él a 62.700. Luego llega a 70.000 y el stop pasa a 66.500. Si el precio retrocede a 66.500, se vende la posición. Has asegurado una subida de unos 6.500 USDT por BTC, un 10,8 %, sin haber tocado el stop a mano."],"mistakes":["Usar una distancia del 1 % o 2 % en activos que se mueven un 5 % al día.","Pensar que el trailing stop también baja cuando el precio cae; solo se mueve a tu favor.","Olvidar que en caídas rápidas se ejecuta a mercado y puede haber deslizamiento."],"faq":[{"q":"¿Cómo funciona un trailing stop?","a":"Sigue al precio a una distancia fija mientras se mueve a tu favor y se queda quieto cuando retrocede. Si el retroceso alcanza la distancia fijada, cierra la posición."},{"q":"¿Qué porcentaje usar en un trailing stop?","a":"No hay uno universal. Muchos traders lo basan en la volatilidad media del activo, para que el ruido normal no lo active."}],"title":"¿Qué es un trailing stop? Cómo funciona en cripto","description":"Qué es un trailing stop o stop dinámico, cómo sigue al precio para proteger ganancias y cómo elegir la distancia según la volatilidad.","related":[["stop-loss","Stop loss (orden de stop)","Un stop loss es una orden que cierra automáticamente tu posición cuando el precio llega a un nivel que has fijado, para limitar la pérdida si el mercado va en tu contra."],["take-profit","Take profit (toma de beneficios)","Un take profit (TP) es una orden que cierra automáticamente tu posición, total o parcialmente, cuando el precio alcanza un objetivo de ganancia que has fijado de antemano."],["stop-limit-order","Orden stop limit","Una orden stop limit combina dos precios: un precio de activación (stop) que, al alcanzarse, coloca automáticamente una orden límite a un precio que tú fijas, de modo que controlas el peor precio aceptable."],["volatility","Volatilidad","La volatilidad mide cuánto y con qué rapidez varía el precio de un activo; en cripto suele ser mucho mayor que en acciones o divisas, con movimientos diarios de varios puntos porcentuales."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit y stop-loss son planes, no seguros"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"es","term":"Precio de marca","aka":["mark price","precio marcado","precio justo"],"short":"El precio de marca es un precio de referencia que calculan los exchanges de futuros a partir del índice spot y otros datos, y que usan para calcular la ganancia no realizada y las liquidaciones.","body":[["El ",["último precio negociado","last-price"]," de un contrato puede saltar de golpe por una orden grande o por poca ",["liquidez","liquidity"],". Para no ",["liquidar","liquidation"]," posiciones por esos picos, los exchanges usan un precio de marca más estable. Se basa en el ",["precio índice","index-price"],", que agrega precios spot de varios exchanges, y suele añadir un componente de base o de la ",["tasa de financiación","funding-rate"],"."],["Tu ganancia o ",["pérdida no realizada","unrealized-pnl"]," y tu precio de liquidación se calculan con el precio de marca. Por eso a veces ves una mecha en el gráfico de último precio que pasa tu precio de liquidación sin que te liquiden: el precio de marca no llegó ahí."],"La fórmula exacta cambia entre plataformas. Algunas permiten elegir si un stop loss se activa por el precio de marca o por el último precio. Revisa ese ajuste en tus órdenes condicionales."],"example":"Tienes un largo con precio de liquidación en 58.500 USDT. Una venta grande hace caer el último precio del perpetuo en tu exchange hasta 58.200 durante dos segundos, mientras el índice spot se mantiene en 59.900. El precio de marca, basado en el índice, baja solo a unos 59.880. Tu posición sigue abierta. Si el índice hubiera caído también por debajo de 58.500, la liquidación sí se habría producido.","mistakes":["Pensar que una mecha en el último precio es lo que decide tu liquidación.","No revisar si tu stop loss usa el precio de marca o el último precio como disparador.","Calcular el beneficio no realizado con el último precio y sorprenderse por la diferencia."],"faq":[{"q":"¿Qué diferencia hay entre precio de marca y último precio?","a":"El último precio es el de la última operación en ese contrato. El precio de marca es una referencia suavizada basada en el índice spot, usada para liquidaciones y PnL no realizado."},{"q":"¿Por qué no me liquidaron si el precio tocó mi liquidación?","a":"Probablemente lo tocó el último precio pero no el precio de marca, que es el que usa el exchange para liquidar."}],"title":"¿Qué es el precio de marca (mark price)?","description":"Qué es el precio de marca en futuros, cómo se calcula a partir del índice y por qué decide tu liquidación en lugar del último precio.","related":[["index-price","Precio índice","El precio índice es el precio spot de referencia de un activo que calcula un exchange como media ponderada de los precios de varios exchanges spot."],["liquidation-price","Precio de liquidación","El precio de liquidación es el precio de marca al que el exchange cerrará de forma forzosa tu posición apalancada porque tu margen habrá bajado al nivel de mantenimiento."],["last-price","Último precio","El último precio es el precio al que se ejecutó la operación más reciente en un mercado concreto, y es el que normalmente ves en el gráfico y en la cabecera del par."],["funding-rate","Tasa de financiación (funding rate)","La tasa de financiación es un pago periódico entre traders largos y cortos de futuros perpetuos que mantiene el precio del contrato cerca del precio spot."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Liquidación: ¿quién presionó el botón de cierre forzoso?"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"es","term":"Convertir (intercambio instantáneo)","aka":["Convert","conversión instantánea","swap","intercambio rápido"],"short":"Convertir es la función de los exchanges que intercambia una criptomoneda por otra con un solo clic a un precio cotizado fijo, sin que tengas que usar el libro de órdenes.","body":[["Eliges la moneda de origen, la de destino y el monto. El sistema te muestra una cotización válida durante unos segundos; si la aceptas, el intercambio se ejecuta a ese precio exacto. Es la forma más sencilla de pasar, por ejemplo, de ",["USDT","usdt"]," a ",["BTC","bitcoin"],"."],"Muchos exchanges anuncian que Convertir no tiene comisión, pero el coste suele estar incluido en el precio cotizado como un pequeño diferencial respecto al precio de mercado. En montos pequeños la diferencia es mínima; en montos grandes puede notarse.",["La alternativa es operar en spot con una ",["orden límite","limit-order"]," o de mercado, con la comisión de maker o taker visible. Para operaciones frecuentes o grandes conviene comparar el resultado final de ambas ",["opciones","options"],"."]],"example":["Supón que quieres pasar 2.000 USDT a ",["ETH","ethereum"],". En el ",["libro de órdenes","order-book"],", ETH está a 2.500 USDT y una orden de mercado con comisión taker del 0,1 % te daría unos 0,7992 ETH. En Convertir te cotizan 2.508 USDT por ETH sin comisión: recibirías unos 0,7974 ETH. La diferencia es de unos 0,0018 ETH, alrededor de 4,4 USDT. Para una compra de 50 USDT casi no importaría, pero en 20.000 USDT serían unos 44 USDT."],"mistakes":["Creer que sin comisión significa sin coste.","No comparar el precio cotizado con el del libro de órdenes en montos grandes.","Esperar demasiado para aceptar y que la cotización caduque con un precio peor."],"faq":[{"q":"¿Convertir es más caro que operar en spot?","a":"A menudo lo es ligeramente, porque el coste va incluido en el precio cotizado. Depende del exchange, del par y del monto."},{"q":"¿Convertir tiene deslizamiento (slippage)?","a":"No en el sentido clásico, porque te garantizan un precio fijo durante unos segundos. El coste ya está incluido en esa cotización."}],"title":"¿Qué es Convertir en un exchange? Swap instantáneo","description":"Qué es la función Convertir de un exchange, cómo funciona la cotización fija y cuál es su coste real frente al trading spot.","related":[["spot-trading","Trading spot (al contado)","El trading spot o al contado es la compraventa directa de criptomonedas al precio actual, en la que recibes el activo de inmediato y pasa a ser tuyo, sin apalancamiento ni contratos de por medio."],["market-order","Orden de mercado (market order)","Una orden de mercado (market order) es una instrucción para comprar o vender de inmediato al mejor precio disponible en el libro de órdenes, priorizando la rapidez de ejecución sobre el precio exacto."],["bid-ask-spread","Spread (diferencial de compra-venta)","El spread o diferencial de compra-venta es la diferencia entre el mejor precio al que alguien quiere comprar (bid) y el mejor precio al que alguien quiere vender (ask) un activo en un momento dado."],["slippage","Deslizamiento (slippage)","El deslizamiento (slippage) es la diferencia entre el precio que esperabas al enviar una orden y el precio medio al que realmente se ejecutó, causada por falta de liquidez o por movimientos rápidos del mercado."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Tu primera operación spot: de 100 a 0.002 BTC"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"es","term":"Acciones tokenizadas","aka":["acciones tokenizadas","tokenized stocks","acciones on-chain"],"short":"Las acciones tokenizadas son tokens en una blockchain que representan acciones de empresas cotizadas y siguen su precio, normalmente respaldadas por acciones reales que guarda un custodio.","body":[["Un emisor compra acciones reales, las deja en custodia y emite tokens que representan una por una o una fracción. Así puedes comprar exposición a una acción con ",["stablecoins","stablecoin"],", en fracciones pequeñas y, según la plataforma, fuera del horario de bolsa."],"No siempre significa que seas accionista. Muchas versiones solo te dan derecho económico al precio y, a veces, a los dividendos, pero no derechos de voto. Lo que tienes en realidad es un derecho frente al emisor, por lo que importa quién es, dónde está regulado y cómo se verifican las reservas.",["Su disponibilidad depende mucho del país, porque son valores regulados. Se diferencian de los ",["perpetuos de acciones","stock-perpetuals"],", que son derivados con ",["apalancamiento","leverage"]," y ",["tasa de financiación","funding-rate"],", sin acciones reales detrás."]],"example":["Supón que una acción cotiza a 200 USD y compras 0,5 tokens que la representan pagando 100 ",["USDC","usdc"],". Si la acción sube a 220 USD, tus tokens valen 110 USDC. Si la empresa paga un dividendo de 1 USD por acción y el emisor lo traslada, recibirías 0,50 USDC. Si el token cotiza fuera del horario de bolsa, su precio puede separarse del de la acción, por ejemplo a 205 cuando el último cierre fue 200, y ajustarse en la apertura."],"mistakes":["Suponer que una acción tokenizada da los mismos derechos que una acción registrada a tu nombre.","No revisar quién es el emisor y quién custodia las acciones reales.","Confundir acciones tokenizadas con perpetuos de acciones apalancados."],"faq":[{"q":"¿Una acción tokenizada es una acción real?","a":"Representa una acción real que guarda un custodio, pero normalmente tienes un derecho económico frente al emisor y no la condición plena de accionista."},{"q":"¿Puedo comprar acciones tokenizadas desde cualquier país?","a":"No. Al ser valores regulados, la disponibilidad depende de tu país de residencia y de la plataforma."}],"title":"¿Qué son las acciones tokenizadas? Cómo funcionan","description":"Qué son las acciones tokenizadas, cómo se respaldan, qué derechos te dan y en qué se diferencian de los perpetuos de acciones.","related":[["stock-perpetuals","Perpetuos de acciones","Los perpetuos de acciones son contratos de futuros perpetuos que siguen el precio de una acción o un índice bursátil, se liquidan en stablecoins y permiten operar en largo o en corto con apalancamiento."],["real-world-assets","Activos del mundo real (RWA)","Los activos del mundo real (RWA) son activos tradicionales, como bonos, inmuebles, oro, acciones o créditos, que se representan como tokens en una blockchain para poder transferirse y usarse on-chain."],["spot-bitcoin-etf","ETF de bitcoin al contado (spot)","Un ETF de bitcoin al contado es un fondo que cotiza en bolsa y compra y guarda bitcoin real, de modo que sus participaciones siguen el precio de BTC sin que tengas que custodiarlo tú."],["usdc","USDC (USD Coin)","USDC es una stablecoin emitida por Circle que busca mantener un valor de 1 dólar estadounidense y está respaldada por reservas en efectivo y activos de corto plazo del Tesoro de EE. UU."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
